import {
  EffectStage,
  InstrumentEffects,
  defaultEffects,
  normalizeEffects,
} from 'app/services/EffectsService/settings';
import { scheduleExpression } from 'app/services/MelodiesService/expression';
import type { NoteExpression } from 'app/services/MelodiesService/types';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';
import {
  DRONE_GRACE_MS,
  droneSpans,
  drumSlot,
  melodicSlotForIndex,
  sampleRegion,
} from 'app/services/SynthesizerService/sampleLayout';
import { sampleDefinition } from 'app/services/SynthesizerService/timbres';
import {
  SampleDefinition,
  Timbre,
} from 'app/services/SynthesizerService/types';

import type {
  Melody,
  NoteInMelody,
  PlaybackMelody,
} from '../MelodiesService/types';
import { MelodyExportError } from './errors';
import { ExportNote, getExportNotes } from './notes';

export const EXPORT_SAMPLE_RATE = 44100;
export const MAX_AUDIO_DURATION_MS = 5 * 60 * 1000;

// The live synthesizer stores C, E and G# for octaves 1–7 in four-second
// slices. Drums use consecutive chromatic slices of increasing length.
export const getSampleRegion = (pitch: number, drums = false) => {
  const index = pitch - 12;
  if (drums) {
    return { ...(drumSlot(index, 143) ?? { offset: 0, duration: 0 }), rate: 1 };
  }
  const { offset, duration, playbackRate } = melodicSlotForIndex(index);
  return { offset, duration, rate: playbackRate };
};

export const getEffectsTail = (settings: InstrumentEffects) => {
  if (settings.bypass) return 0.02;
  const normalized = normalizeEffects('', settings);
  const tail = (stage: EffectStage) => {
    const feedback = stage.delay.feedback / 100;
    const repeats =
      feedback > 0 ? Math.ceil(Math.log(0.001) / Math.log(feedback)) : 0;
    return (
      0.03 +
      (stage.reverb.enabled ? 2 : 0) +
      (stage.delay.enabled ? (stage.delay.time / 1000) * (1 + repeats) : 0)
    );
  };
  return (
    tail(normalized) +
    (normalized.pedals ?? [])
      .filter(pedal => pedal.enabled)
      .flatMap(pedal => pedal.stages)
      .reduce((sum, stage) => sum + tail(stage), 0)
  );
};

export const scheduleExportNotes = (
  audio: OfflineAudioContext,
  sample: AudioBuffer,
  destination: AudioNode,
  notes: ExportNote[],
  drums: boolean,
  definition?: SampleDefinition,
) => {
  const schedule = (
    region: {
      offset: number;
      duration: number;
      rate: number;
      loop?: { loopStart: number; loopEnd: number } | null;
    },
    start: number,
    end: number,
    gain = 1,
    expression?: NoteExpression,
  ) => {
    if (
      !region.duration ||
      region.offset < 0 ||
      region.offset + region.duration > sample.duration
    )
      return;
    const source = audio.createBufferSource();
    source.buffer = sample;
    source.playbackRate.value = region.rate;
    if (expression && !drums)
      scheduleExpression(source.detune, expression, start, end - start);
    const filter = audio.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = audio.sampleRate / 2;
    filter.Q.value = Math.SQRT1_2;
    const envelope = definition ? audio.createGain() : undefined;
    if (envelope) envelope.gain.value = gain;
    source.connect(filter);
    filter.connect(envelope ?? destination);
    envelope?.connect(destination);
    const loop = region.loop;
    if (loop) {
      source.loop = true;
      source.loopStart = region.offset + loop.loopStart;
      source.loopEnd = region.offset + loop.loopEnd;
      source.start(start, region.offset);
    } else source.start(start, region.offset, region.duration);
    const release = definition?.release ?? 0;
    envelope?.gain.setValueAtTime(gain, end);
    envelope?.gain.linearRampToValueAtTime(0, end + release);
    source.stop(end + release);
  };
  notes.forEach(note => {
    const selected =
      definition &&
      sampleRegion(note.pitch - 12, definition, drums, sample.duration);
    const region = selected
      ? { ...selected, rate: selected.playbackRate }
      : definition
      ? undefined
      : getSampleRegion(note.pitch, drums);
    if (region)
      schedule(
        region,
        note.start / 1000,
        note.end / 1000,
        1,
        definition?.pitchedNotes ? undefined : note.expression,
      );
  });
  if (definition?.drones)
    droneSpans(notes).forEach(span => {
      definition.drones!.forEach(drone =>
        schedule(
          { ...drone, rate: 1, loop: drone },
          span.start / 1000,
          span.end / 1000,
          drone.gain,
        ),
      );
    });
};

export const renderMelodyMix = async (
  melody: PlaybackMelody,
  effectsFor: (timbre: Timbre) => InstrumentEffects | undefined,
): Promise<AudioBuffer> => {
  const parts = new Map<Timbre, NoteInMelody[]>();
  for (const note of melody.notes) {
    const timbre = note.timbre ?? melody.timbre;
    const part = parts.get(timbre);
    if (part) part.push(note);
    else parts.set(timbre, [note]);
  }
  if (!parts.size) throw new MelodyExportError('This melody has no notes yet.');
  const tracks = Array.from(parts, ([timbre, part]) => {
    const notes = getExportNotes({ ...melody, timbre, notes: part });
    const end = notes.reduce((max, note) => Math.max(max, note.end), 0);
    const definition = sampleDefinition(timbre);
    const settings = effectsFor(timbre) ?? defaultEffects(timbre);
    const duration =
      end / 1000 +
      (definition.drones ? DRONE_GRACE_MS / 1000 : 0) +
      definition.release +
      getEffectsTail(settings);
    return { timbre, notes, end, definition, settings, duration };
  });
  if (tracks.some(track => track.end > MAX_AUDIO_DURATION_MS)) {
    throw new MelodyExportError(
      'Audio export supports melodies up to 5 minutes. Choose MIDI for longer melodies.',
    );
  }
  if (!window.OfflineAudioContext) {
    throw new MelodyExportError(
      'This browser does not support audio export. Choose MIDI or update your browser.',
    );
  }
  const audio = new OfflineAudioContext(
    2,
    Math.ceil(
      Math.max(...tracks.map(track => track.duration)) * EXPORT_SAMPLE_RATE,
    ),
    EXPORT_SAMPLE_RATE,
  );
  const samples = await Promise.all(
    tracks.map(async ({ definition }) => {
      const response = await fetch(
        `${process.env.PUBLIC_URL || ''}/samples/library/${definition.file}`,
      );
      if (!response.ok)
        throw new MelodyExportError(
          'Could not load instrument sound. Check your connection and retry the download.',
        );
      return audio.decodeAudioData(await response.arrayBuffer());
    }),
  );
  const racks: ReturnType<typeof createEffectsRack>[] = [];
  try {
    tracks.forEach(({ timbre, settings, notes, definition }, i) => {
      const rack = createEffectsRack(audio, audio.destination, settings);
      racks.push(rack);
      scheduleExportNotes(
        audio,
        samples[i],
        rack.input,
        notes,
        timbre === 'drums',
        definition,
      );
    });
    return await audio.startRendering();
  } finally {
    racks.forEach(rack => rack.dispose());
  }
};

export const renderMelodyAudio = (
  melody: Melody,
  settings?: InstrumentEffects,
) => renderMelodyMix(melody, () => settings);

export const pcm16 = (sample: number) => {
  const clamped = Math.max(-1, Math.min(1, sample));
  return Math.round(clamped * (clamped < 0 ? 32768 : 32767));
};

export const encodeWav = (audio: AudioBuffer): ArrayBuffer => {
  const channels = audio.numberOfChannels;
  const bytesPerFrame = channels * 2;
  const buffer = new ArrayBuffer(44 + audio.length * bytesPerFrame);
  const view = new DataView(buffer);
  const text = (offset: number, value: string) => {
    Array.from(value).forEach((char, i) =>
      view.setUint8(offset + i, char.charCodeAt(0)),
    );
  };
  text(0, 'RIFF');
  view.setUint32(4, buffer.byteLength - 8, true);
  text(8, 'WAVE');
  text(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, channels, true);
  view.setUint32(24, audio.sampleRate, true);
  view.setUint32(28, audio.sampleRate * bytesPerFrame, true);
  view.setUint16(32, bytesPerFrame, true);
  view.setUint16(34, 16, true);
  text(36, 'data');
  view.setUint32(40, audio.length * bytesPerFrame, true);
  const data = Array.from({ length: channels }, (_, i) =>
    audio.getChannelData(i),
  );
  for (let frame = 0; frame < audio.length; frame++) {
    for (let channel = 0; channel < channels; channel++) {
      view.setInt16(
        44 + frame * bytesPerFrame + channel * 2,
        pcm16(data[channel][frame]),
        true,
      );
    }
  }
  return buffer;
};
